"""Actions analyzer — detects calendar events needing user attention.

Scans events for conditions like all attendees declining, producing
alerts with recommended actions.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from typing import Any


@dataclass
class DeclinedMeetingAlert:
    """Alert for a meeting where all non-self attendees declined."""

    event: dict[str, Any]
    user_is_organizer: bool
    all_others_declined: bool
    declined_attendees: list[str]
    total_attendees: int


def detect_declined_meetings(
    events: list[dict[str, Any]],
    *,
    window_hours: int = 24,
    now: datetime | None = None,
) -> list[DeclinedMeetingAlert]:
    """Find events where all non-self attendees have declined.

    Args:
        events: Normalized calendar events from the collector.
        window_hours: Only consider events starting within this many hours.
        now: Override current time (for testing).

    Returns:
        List of alerts for events needing attention.
    """
    if now is None:
        now = datetime.now(tz=timezone.utc)

    cutoff = now + timedelta(hours=window_hours)
    alerts: list[DeclinedMeetingAlert] = []

    for event in events:
        if event.get("all_day", False):
            continue
        if event.get("status") == "cancelled":
            continue

        start_str = event.get("start", "")
        if not start_str or len(start_str) <= 10:
            continue

        try:
            start_dt = datetime.fromisoformat(start_str)
            if start_dt.tzinfo is None:
                continue
            start_utc = start_dt.astimezone(timezone.utc)
        except (ValueError, TypeError):
            continue

        if start_utc < now or start_utc > cutoff:
            continue

        attendees = event.get("attendees", [])
        others = [a for a in attendees if not a.get("self")]
        if not others:
            continue

        declined = [
            a["email"] for a in others if a.get("response_status") == "declined"
        ]
        if len(declined) == len(others):
            alerts.append(
                DeclinedMeetingAlert(
                    event=event,
                    user_is_organizer=event.get("organizer_self", False),
                    all_others_declined=True,
                    declined_attendees=declined,
                    total_attendees=len(others),
                )
            )

    # Sort by start time
    alerts.sort(key=lambda a: a.event.get("start", ""))
    return alerts
